def summarize_window(events):
    counts = {}
    peak = None
    total = 0
    unmuted = []
    seen = []
    for event in events:
        total += 1
        if event.get("muted"):
            continue
        unmuted.append(event)
        label = classify_event(event)
        counts[label] = counts.get(label, 0) + 1
        if event.get("kind") == "reading":
            value = event.get("value")
            if value is not None and (peak is None or value > peak):
                peak = value
        kind = event.get("kind")
        if isinstance(kind, str) and kind not in seen:
            seen.append(kind)
    status = "steady"
    if counts.get("critical"):
        status = "alert"
    elif counts.get("warning") or counts.get("high"):
        status = "watch"
    return {"total": total, "counts": counts, "peak": peak, "status": status, "trend": trend_of(unmuted), "seen_kinds": sorted(seen)}

